  grad.addColorStop(0,'#000020');
  grad.addColorStop(1,'#000040');
  ctx.fillStyle = grad;
  ctx.fillRect(0,0,width,height);
  // stars
  ctx.fillStyle='white';
  ctx.shadowBlur=2;
  ctx.shadowColor='white';
  for(let s of stars){
