    ctx.fill();
  }
  ctx.shadowBlur=0;
  // ship (triangle with stroke)
  ctx.fillStyle='cyan';
  ctx.strokeStyle='white';
  ctx.lineWidth=2;
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h/2);
  ctx.lineTo(ship.x + ship.w, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
